mapper.select:
select t5.portal_id as portalId, t5.portal_name as portalName, t4.menu_name as menuName, t4.menu_id as menuId, t3.analysis_tpl_name as analysisTplName, t3.analysis_tpl_id as analysisTplId, t6.date_granularity as dateGranularity from bi_ssm.ssm_analysis_tpl_cfg_prod t1 inner join bi_ssm.ssm_analysis_tpl_base t3 on t1.analysis_tpl_id = t3.analysis_tpl_id inner join bi_ssm.ssm_portal_menu t4 on t1.analysis_tpl_id = t4.content_ref_id inner join bi_ssm.ssm_portal t5 on t4.portal_id = t5.portal_id inner join bi_ssm.ssm_analysis_tpl_cache_cfg t6 on t4.menu_id = t6.analysis_tpl_menu_id where 1=1 and t1.is_latest = 1 and t3.is_active = 1 and t4.is_active = 1 and t6.is_active = 1
and t6.analysis_tpl_menu_id == #{menuId}
order by t5.sort_id, t4.sort_id
